/// Temporary guest accounts for unauthenticated users during registration
/// and login flows.
///
/// This table stores guest user identities that are created during the
/// authentication process. Guest accounts serve as temporary placeholders
/// for users who are in the process of registering or logging in. Each guest
/// account has email authentication credentials and can establish sessions
/// for temporary access.
///
/// Guest accounts are typically short-lived and may be automatically cleaned
/// up after successful registration or login completion. They provide a way
/// to track unauthenticated user activity while maintaining proper
/// authentication flow separation.
///
/// Relationships:
/// - Has many {@link multi_user_todo_guest_sessions} for temporary access
/// - References {@link multi_user_todo_audit_logs} for security tracking
/// - May be converted to {@link multi_user_todo_members} upon successful
/// registration
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model multi_user_todo_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address for guest authentication and identification.
  email String

  /// Hashed password for guest account security.
  password_hash String

  /// Timestamp when the guest account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was soft-deleted, null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions multi_user_todo_guest_sessions[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([created_at])
  @@index([updated_at])
}

