  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([multi_user_todo_guest_id, created_at], map: "multi_user_todo_guest_sessions_multi_user_todo_guest_i_a66d6799")
}

/// Registered user accounts with email/password authentication credentials.
///
/// This table stores the core identity and authentication information for
/// registered users of the multi-user Todo application. Each member
/// represents a unique user who can create, manage, and organize their
/// private todo lists. The table includes authentication credentials (email
/// and password hash) along with user profile information.
///
/// Users can manage their account settings, including password changes and
/// account deletion. All operations performed by members are tracked through
/// session tables and audit logs. Members have complete privacy isolation -
/// they can only access their own todos and cannot view other users' data.
///
/// {@link multi_user_todo_member_sessions.id} tracks authentication sessions
/// for this user.
/// {@link multi_user_todo_member_password_resets.id} handles password
/// recovery workflows.
/// {@link multi_user_todo_todos.id} contains all todos owned by this user.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model multi_user_todo_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used for authentication and account identification.
  email String

  /// Hashed password for secure authentication using industry-standard hashing
  /// algorithms.
  password_hash String

  /// User's visible name displayed throughout the application interface.
  display_name String

  /// Timestamp when the user account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the user account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the user account was soft-deleted, allowing for account
  /// recovery within retention period.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions multi_user_todo_member_sessions[]
  passwordResets multi_user_todo_member_password_resets[]
  auditLogs multi_user_todo_audit_logs[]
  todos multi_user_todo_todos[]
  todoFilterSettings multi_user_todo_todo_filter_settings[]
  todoViewStats multi_user_todo_todo_view_stats[]
  todoSortingPreference multi_user_todo_todo_sorting_preferences?
  editHistories multi_user_todo_edit_histories[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([created_at])
  @@index([display_name])
}

