  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  member multi_user_todo_members @relation(fields: [multi_user_todo_member_id], references: [id], onDelete: Cascade, map: "multi_user_todo_todo_filter_settings_multi_user_todo_m_857bc11d")

