import type { IPageIMultiUserTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMultiUserTodoAdmin";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
