/**
 * Test advanced filtering capabilities of admin accounts search endpoint.
 *
 * Verify that search functionality works correctly with email pattern matching,
 * display name filtering, case-insensitive searches, date range filtering,
 * and soft-delete filtering.
 */
export async function test_api_admin_accounts_filtering_email_display_name(
  connection: api.IConnection,
): Promise<void> {
  // Create separate connections for each admin to avoid token conflicts
  const adminConnections: api.IConnection[] = [];
  // Create multiple test admin accounts with varied email patterns and display names
  const testAdmins = ArrayUtil.repeat(6, (index) => {
    const baseName = ["admin", "super", "power", "master", "root", "sys"][
      index
    ];
    return {
      email:
        index === 0
          ? `test.${baseName}@example.com`
          : index === 1
            ? `${baseName}_user@gmail.com`
            : index === 2
              ? `${baseName}.support@company.org`
              : index === 3
                ? `admin_${baseName}@test.co.uk`
                : index === 4
                  ? `${baseName}123@domain.io`
                  : `${baseName}.system@enterprise.net`,
      password: "password123",
      display_name:
        index === 0
          ? `Super ${baseName.charAt(0).toUpperCase() + baseName.slice(1)}`
          : index === 1
            ? `${baseName.toUpperCase()} Administrator`
            : index === 2
              ? `Main ${baseName}`
              : index === 3
                ? `${baseName} Manager`
                : index === 4
                  ? `Lead ${baseName}`
                  : `${baseName} Director`,
    } satisfies IMultiUserTodoAdmin.IJoin;
  });
  // Create admin accounts using utility function
  const createdAdmins: IMultiUserTodoAdmin.IAuthorized[] = [];
  for (const testAdmin of testAdmins) {
    const adminConnection: api.IConnection = { host: connection.host };
    adminConnections.push(adminConnection);
    const createdAdmin = await authorize_admin_join(adminConnection, {
      body: testAdmin,
    });
    typia.assert(createdAdmin);
    createdAdmins.push(createdAdmin);
  }
  // Save timestamps for date range filtering tests
  const earliestCreatedAt = createdAdmins[0].created_at;
  const middleCreatedAt = createdAdmins[2].created_at;
  const latestCreatedAt = createdAdmins[5].created_at;
  // Wait a moment to ensure updated_at timestamps differ
  await new Promise((resolve) => setTimeout(resolve, 100));
  // Use one admin connection for all search tests
  const searchConnection = adminConnections[0];
  // TEST 1: Basic email pattern matching
  const emailSearch = await api.functional.multiUserTodo.admins.index(
    searchConnection,
    {
      body: {
        search: "example.com",
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(emailSearch);
  TestValidator.equals(
    "should find admin with example.com email",
    emailSearch.data.length,
    1,
  );
  TestValidator.equals(
    "email should match pattern",
    emailSearch.data[0].email,
    testAdmins[0].email,
  );
  // TEST 2: Display name partial match
  const displayNameSearch = await api.functional.multiUserTodo.admins.index(
    searchConnection,
    {
      body: {
        search: "Manager",
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(displayNameSearch);
  TestValidator.predicate(
    "should find at least one manager",
    displayNameSearch.data.length >= 1,
  );
  // TEST 3: Case-insensitive search
  const caseInsensitiveSearch = await api.functional.multiUserTodo.admins.index(
    searchConnection,
    {
      body: {
        search: "SUPER", // uppercase search
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(caseInsensitiveSearch);
  // Should find admin with "Super" in display name (testAdmins[0])
  TestValidator.predicate(
    "case-insensitive search should find matches",
    caseInsensitiveSearch.data.length >= 1,
  );
  // TEST 4: Date range filtering (created_at)
  const dateRangeSearch = await api.functional.multiUserTodo.admins.index(
    searchConnection,
    {
      body: {
        created_at_start: earliestCreatedAt,
        created_at_end: latestCreatedAt,
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(dateRangeSearch);
  TestValidator.equals(
    "date range should include all admins",
    dateRangeSearch.data.length,
    6,
  );
  // TEST 5: Pagination testing
  const page1 = await api.functional.multiUserTodo.admins.index(
    searchConnection,
    {
      body: {
        page: 1,
        limit: 3,
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals("page 1 should have 3 items", page1.data.length, 3);
  TestValidator.equals(
    "page 1 current should be 1",
    page1.pagination.current,
    1,
  );
  TestValidator.equals("page 1 limit should be 3", page1.pagination.limit, 3);
  const page2 = await api.functional.multiUserTodo.admins.index(
    searchConnection,
    {
      body: {
        page: 2,
        limit: 3,
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(page2);
  TestValidator.equals("page 2 should have 3 items", page2.data.length, 3);
  TestValidator.equals(
    "page 2 current should be 2",
    page2.pagination.current,
    2,
  );
  // TEST 6: Combined search with pagination
  const combinedSearch = await api.functional.multiUserTodo.admins.index(
    searchConnection,
    {
      body: {
        search: "admin",
        limit: 2,
        page: 1,
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(combinedSearch);
  TestValidator.predicate(
    "combined search should return paginated results",
    combinedSearch.data.length <= 2,
  );
  // TEST 7: Empty search (should return all when no criteria)
  const emptySearch = await api.functional.multiUserTodo.admins.index(
    searchConnection,
    {
      body: {} satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(emptySearch);
  TestValidator.equals(
    "empty search should return all admins",
    emptySearch.data.length,
    6,
  );
  // Note: Cannot test include_deleted parameter since we cannot delete admin accounts
  // in this test (no deletion endpoint available in the provided APIs)
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IMultiUserTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIMultiUserTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMultiUserTodoAdmin";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

/**
 * Test edge cases and boundary conditions for the admin accounts search endpoint.
 * Verify behavior when no records match search criteria, when using extreme date
 * ranges, and when searching with empty or invalid parameters. Test pagination
 * edge cases such as requesting pages beyond the available data range and using
 * minimum/maximum limit values. Validate that the system handles these scenarios
 * gracefully and returns appropriate empty results with correct pagination metadata.
 */
export async function test_api_admin_accounts_empty_results_edge_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create admin connection for authorization
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, { body: {} });
  // 2. Test default empty search - should return at least current admin
  const emptySearch = await api.functional.multiUserTodo.admins.index(
    adminConnection,
    {
      body: {} satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(emptySearch);
  TestValidator.predicate(
    "empty search returns at least current admin",
    emptySearch.data.length >= 1,
  );
  TestValidator.equals(
    "pagination metadata valid for empty search",
    emptySearch.pagination.current,
    1,
  );
  TestValidator.predicate(
    "records count matches data length",
    emptySearch.pagination.records >= emptySearch.data.length,
  );
  TestValidator.predicate(
    "pages calculated correctly",
    emptySearch.pagination.pages >= 1,
  );
  // 3. Test non-matching search term - should return empty results
  const impossibleSearch = await api.functional.multiUserTodo.admins.index(
    adminConnection,
    {
      body: {
        search: typia.random<string & tags.Format<"uuid">>(), // UUID unlikely to match email/display name
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(impossibleSearch);
  TestValidator.equals(
    "impossible search returns empty data array",
    impossibleSearch.data.length,
    0,
  );
  TestValidator.equals(
    "records count is 0 for impossible search",
    impossibleSearch.pagination.records,
    0,
  );
  TestValidator.equals(
    "pages count is 0 for impossible search",
    impossibleSearch.pagination.pages,
    0,
  );
  TestValidator.equals(
    "current page is 1 for impossible search",
    impossibleSearch.pagination.current,
    1,
  );
  // 4. Test future date range - no records should exist
  const futureDate = new Date(Date.now() + 1000 * 60 * 60 * 24 * 365); // 1 year future
  const futureSearch = await api.functional.multiUserTodo.admins.index(
    adminConnection,
    {
      body: {
        created_at_start: futureDate.toISOString(),
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(futureSearch);
  TestValidator.equals(
    "future date range returns empty results",
    futureSearch.data.length,
    0,
  );
  // 5. Test pagination edge case: page beyond available data
  const pageBeyond = await api.functional.multiUserTodo.admins.index(
    adminConnection,
    {
      body: {
        page: 100,
        limit: 1,
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(pageBeyond);
  TestValidator.equals(
    "page beyond data returns empty results",
    pageBeyond.data.length,
    0,
  );
  TestValidator.equals(
    "current page is requested page",
    pageBeyond.pagination.current,
    100,
  );
  // 6. Test minimum and maximum limit values
  const minLimit = await api.functional.multiUserTodo.admins.index(
    adminConnection,
    {
      body: {
        limit: 1,
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(minLimit);
  TestValidator.equals(
    "minimum limit value accepted",
    minLimit.pagination.limit,
    1,
  );
  const maxLimit = await api.functional.multiUserTodo.admins.index(
    adminConnection,
    {
      body: {
        limit: 100,
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(maxLimit);
  TestValidator.equals(
    "maximum limit value accepted",
    maxLimit.pagination.limit,
    100,
  );
  // 7. Test include_deleted when no deleted accounts exist
  const withDeleted = await api.functional.multiUserTodo.admins.index(
    adminConnection,
    {
      body: {
        include_deleted: true,
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(withDeleted);
  // Should at least include the current admin (not deleted)
  TestValidator.predicate(
    "include_deleted includes non-deleted admins",
    withDeleted.data.length >= 1,
  );
  // 8. Test combination of impossible filters
  const combinedImpossible = await api.functional.multiUserTodo.admins.index(
    adminConnection,
    {
      body: {
        search: "NONEXISTENT12345",
        created_at_start: new Date(
          Date.now() + 1000 * 60 * 60 * 24,
        ).toISOString(), // tomorrow
        created_at_end: new Date(
          Date.now() + 1000 * 60 * 60 * 24 * 2,
        ).toISOString(), // day after tomorrow
        updated_at_start: new Date(
          Date.now() - 1000 * 60 * 60 * 24 * 365 * 10,
        ).toISOString(), // 10 years ago
        updated_at_end: new Date(
          Date.now() - 1000 * 60 * 60 * 24 * 365 * 9,
        ).toISOString(), // 9 years ago
      } satisfies IMultiUserTodoAdmin.IRequest,
    },
  );
  typia.assert(combinedImpossible);
  TestValidator.equals(
    "combined impossible filters returns empty results",
    combinedImpossible.data.length,
    0,
  );
  // 9. Test that all empty result sets have consistent pagination metadata
  const emptyResults = [
    impossibleSearch,
    futureSearch,
    pageBeyond,
    combinedImpossible,
  ];
  for (const [index, result] of emptyResults.entries()) {
    if (result.pagination.records === 0) {
      TestValidator.equals(
        `empty result ${index}: pages is 0 when records is 0`,
        result.pagination.pages,
        0,
      );
      TestValidator.equals(
        `empty result ${index}: data array is empty`,
        result.data.length,
        0,
      );
    }
  }
}

