/**
 * Test updating basic system configuration settings with different data types.
 * Verify that the configuration value is properly validated against the specified
 * data type (string, number, boolean, json). Validate that the version number
 * increments correctly and the updated_at timestamp is updated.
 */
export async function test_api_system_configuration_update_basic_settings(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authentication setup
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
    },
  });
  typia.assert(admin);
  // Assume a pre-existing configuration ID for testing
  // In a real test environment, this would be created by a setup script
  const configurationId = typia.random<string & tags.Format<"uuid">>();
  // 2. Test string data type update
  const stringUpdate =
    await api.functional.multiUserTodo.admin.system_configurations.update(
      adminConnection,
      {
        configurationId,
        body: {
          config_value: RandomGenerator.paragraph({ sentences: 3 }),
          data_type: "string",
          scope: "global",
          description: RandomGenerator.paragraph({ sentences: 1 }),
          is_active: true,
        } satisfies IMultiUserTodoSystemConfiguration.IUpdate,
      },
    );
  typia.assert(stringUpdate);
  TestValidator.equals(
    "data_type should be string",
    stringUpdate.data_type,
    "string",
  );
  TestValidator.predicate(
    "version should be at least 1",
    stringUpdate.version >= 1,
  );
  TestValidator.predicate(
    "updated_at should be valid date",
    new Date(stringUpdate.updated_at).getTime() > 0,
  );
  // 3. Test number data type update
  const numberUpdate =
    await api.functional.multiUserTodo.admin.system_configurations.update(
      adminConnection,
      {
        configurationId,
        body: {
          config_value: typia
            .random<
              number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<1000>
            >()
            .toString(),
          data_type: "number",
          scope: "component",
          description: RandomGenerator.paragraph({ sentences: 2 }),
          is_active: false,
        } satisfies IMultiUserTodoSystemConfiguration.IUpdate,
      },
    );
  typia.assert(numberUpdate);
  TestValidator.equals(
    "data_type should be number",
    numberUpdate.data_type,
    "number",
  );
  TestValidator.equals(
    "version should increment from previous",
    numberUpdate.version,
    stringUpdate.version + 1,
  );
  TestValidator.predicate(
    "updated_at should be newer",
    new Date(numberUpdate.updated_at).getTime() >
      new Date(stringUpdate.updated_at).getTime(),
  );
  // Verify number validation by attempting to parse config_value
  const parsedNumber = Number(numberUpdate.config_value);
  TestValidator.predicate(
    "config_value should be valid number",
    !isNaN(parsedNumber),
  );
  // 4. Test boolean data type update
  const booleanUpdate =
    await api.functional.multiUserTodo.admin.system_configurations.update(
      adminConnection,
      {
        configurationId,
        body: {
          config_value: "true",
          data_type: "boolean",
          scope: "environment",
          description: RandomGenerator.paragraph({ sentences: 1 }),
          is_active: true,
        } satisfies IMultiUserTodoSystemConfiguration.IUpdate,
      },
    );
  typia.assert(booleanUpdate);
  TestValidator.equals(
    "data_type should be boolean",
    booleanUpdate.data_type,
    "boolean",
  );
  TestValidator.equals(
    "config_value should be 'true'",
    booleanUpdate.config_value,
    "true",
  );
  TestValidator.equals(
    "version should increment",
    booleanUpdate.version,
    numberUpdate.version + 1,
  );
  TestValidator.predicate(
    "updated_at should be newer",
    new Date(booleanUpdate.updated_at).getTime() >
      new Date(numberUpdate.updated_at).getTime(),
  );
  // 5. Test json data type update
  const jsonData = {
    nested: {
      stringValue: RandomGenerator.name(),
      numberValue: typia.random<
        number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
      >(),
      booleanValue: true,
      arrayValue: ArrayUtil.repeat(3, () => RandomGenerator.alphabets(5)),
    },
  };
  const jsonUpdate =
    await api.functional.multiUserTodo.admin.system_configurations.update(
      adminConnection,
      {
        configurationId,
        body: {
          config_value: JSON.stringify(jsonData),
          data_type: "json",
          scope: "global",
          description: RandomGenerator.paragraph({ sentences: 2 }),
          is_active: booleanUpdate.is_active,
        } satisfies IMultiUserTodoSystemConfiguration.IUpdate,
      },
    );
  typia.assert(jsonUpdate);
  TestValidator.equals(
    "data_type should be json",
    jsonUpdate.data_type,
    "json",
  );
  TestValidator.equals(
    "version should increment",
    jsonUpdate.version,
    booleanUpdate.version + 1,
  );
  TestValidator.predicate(
    "updated_at should be newer",
    new Date(jsonUpdate.updated_at).getTime() >
      new Date(booleanUpdate.updated_at).getTime(),
  );
  // Verify JSON is valid
  const parsedJson = JSON.parse(jsonUpdate.config_value);
  TestValidator.predicate(
    "config_value should be valid JSON",
    typeof parsedJson === "object",
  );
  // 6. Validate complete entity structure after all updates
  TestValidator.equals(
    "id should remain constant",
    jsonUpdate.id,
    configurationId,
  );
  TestValidator.predicate(
    "config_key should be present",
    jsonUpdate.config_key.length > 0,
  );
  TestValidator.predicate(
    "description should be present",
    jsonUpdate.description.length > 0,
  );
  TestValidator.predicate(
    "scope should be valid",
    ["global", "component", "environment"].includes(jsonUpdate.scope),
  );
  TestValidator.predicate(
    "created_at should be valid",
    new Date(jsonUpdate.created_at).getTime() > 0,
  );
  TestValidator.predicate(
    "updated_at should be after created_at",
    new Date(jsonUpdate.updated_at).getTime() >=
      new Date(jsonUpdate.created_at).getTime(),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IMultiUserTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoAdmin";
import type { IMultiUserTodoSystemConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoSystemConfiguration";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";
import { generate_random_multi_user_todo_admin_system_configurations_create } from "../../../generate/generate_random_multi_user_todo_admin_system_configurations_create";
import { prepare_random_multi_user_todo_system_configuration } from "../../../prepare/prepare_random_multi_user_todo_system_configuration";

/**
 * Test toggling the activation status of a system configuration.
 * Verify that when is_active is changed from true to false (or vice versa),
 * the configuration properly reflects the new activation state.
 * Validate that other configuration fields remain unchanged unless explicitly
 * modified. Test that version tracking increments correctly for activation
 * status changes.
 */
export async function test_api_system_configuration_activation_toggle(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as admin
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
    } satisfies IMultiUserTodoAdmin.IJoin,
  });
  // 2. Create a system configuration with is_active = true
  const created =
    await generate_random_multi_user_todo_admin_system_configurations_create(
      adminConnection,
      {
        body: {
          config_key: `test.config.${RandomGenerator.alphaNumeric(8)}`,
          config_value: "initial value",
          data_type: "string" as const,
          scope: "global" as const,
          description: RandomGenerator.paragraph({ sentences: 2 }),
          is_active: true,
        } satisfies IMultiUserTodoSystemConfiguration.ICreate,
      },
    );
  typia.assert(created);
  // Verify initial state: active with version 1
  TestValidator.equals("initial is_active is true", created.is_active, true);
  TestValidator.equals("initial version is 1", created.version, 1);
  // Store original values for comparison
  const originalConfigKey = created.config_key;
  const originalConfigValue = created.config_value;
  const originalDataType = created.data_type;
  const originalScope = created.scope;
  const originalDescription = created.description;
  // 3. Toggle is_active from true to false
  const toggledToFalse =
    await api.functional.multiUserTodo.admin.system_configurations.update(
      adminConnection,
      {
        configurationId: created.id,
        body: {
          is_active: false,
        } satisfies IMultiUserTodoSystemConfiguration.IUpdate,
      },
    );
  typia.assert(toggledToFalse);
  // Verify activation status changed to false
  TestValidator.equals(
    "is_active changed to false",
    toggledToFalse.is_active,
    false,
  );
  // Verify version incremented to 2
  TestValidator.equals("version incremented to 2", toggledToFalse.version, 2);
  // Verify other fields unchanged
  TestValidator.equals(
    "config_key unchanged",
    toggledToFalse.config_key,
    originalConfigKey,
  );
  TestValidator.equals(
    "config_value unchanged",
    toggledToFalse.config_value,
    originalConfigValue,
  );
  TestValidator.equals(
    "data_type unchanged",
    toggledToFalse.data_type,
    originalDataType,
  );
  TestValidator.equals("scope unchanged", toggledToFalse.scope, originalScope);
  TestValidator.equals(
    "description unchanged",
    toggledToFalse.description,
    originalDescription,
  );
  // 4. Toggle is_active back from false to true
  const toggledToTrue =
    await api.functional.multiUserTodo.admin.system_configurations.update(
      adminConnection,
      {
        configurationId: created.id,
        body: {
          is_active: true,
        } satisfies IMultiUserTodoSystemConfiguration.IUpdate,
      },
    );
  typia.assert(toggledToTrue);
  // Verify activation status changed back to true
  TestValidator.equals(
    "is_active changed back to true",
    toggledToTrue.is_active,
    true,
  );
  // Verify version incremented to 3
  TestValidator.equals("version incremented to 3", toggledToTrue.version, 3);
  // Verify other fields still unchanged
  TestValidator.equals(
    "config_key still unchanged",
    toggledToTrue.config_key,
    originalConfigKey,
  );
  TestValidator.equals(
    "config_value still unchanged",
    toggledToTrue.config_value,
    originalConfigValue,
  );
  TestValidator.equals(
    "data_type still unchanged",
    toggledToTrue.data_type,
    originalDataType,
  );
  TestValidator.equals(
    "scope still unchanged",
    toggledToTrue.scope,
    originalScope,
  );
  TestValidator.equals(
    "description still unchanged",
    toggledToTrue.description,
    originalDescription,
  );
  // 5. Additional validation: Ensure version increments are monotonic
  TestValidator.predicate(
    "version monotonic increase",
    created.version < toggledToFalse.version,
  );
  TestValidator.predicate(
    "version monotonic increase 2",
    toggledToFalse.version < toggledToTrue.version,
  );
  // 6. Validate timestamps: updated_at should be more recent than created_at
  const createdDate = new Date(created.created_at).getTime();
  const updatedDate = new Date(toggledToTrue.updated_at).getTime();
  TestValidator.predicate(
    "updated_at after created_at",
    updatedDate > createdDate,
  );
}

