  const backupTypes = [
    "full",
    "incremental",
    "differential",
    "manual",
    "scheduled",
    "recovery",
  ] as const;
  const statuses = [
    "pending",
    "in_progress",
    "completed",
    "failed",
    "cancelled",
  ] as const;
  for (const backupType of backupTypes) {
    for (const status of statuses) {
      const response =
        await api.functional.multiUserTodo.admin.backup_logs.index(
          adminConnection,
          {
            body: {
              backup_type: backupType,
              status: status,
              page: 1,
              limit: 10,
