  TestValidator.equals(
    "member ID matches creator",
    retrievedTodo.member.id,
    memberAuth.id,
  );
  TestValidator.equals(
    "member email matches",
    retrievedTodo.member.email,
    memberAuth.email,
  );
  TestValidator.equals(
    "member display name matches",
    retrievedTodo.member.display_name,
    memberAuth.display_name,
  );
}

