/**
 * Test unauthorized access to another user's trash entry.
 * 1. Create and authenticate as first member user (User A)
 * 2. Create a todo for User A (though we can't delete/create trash entry)
 * 3. Create and authenticate as second member user (User B)
 * 4. Attempt to retrieve a random trash entry ID as User B
 * 5. Validate that system rejects with authorization error
 */
export async function test_api_todo_trash_entry_unauthorized_access(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create and authenticate User A
  const userAConnection: api.IConnection = { host: connection.host };
  const userA = await authorize_member_join(userAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IMultiUserTodoMember.IJoin,
  });
  typia.assert(userA);
  // 2. Create a todo for User A
  const todo = await generate_random_multi_user_todo_member_todos_create(
    userAConnection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
      } satisfies IMultiUserTodoTodo.ICreate,
    },
  );
  typia.assert(todo);
  // Note: We don't have delete/trash creation endpoints to actually create a trash entry
  // But the test is about unauthorized access, so we can still test with random UUID
  // 3. Create and authenticate User B
  const userBConnection: api.IConnection = { host: connection.host };
  const userB = await authorize_member_join(userBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IMultiUserTodoMember.IJoin,
  });
  typia.assert(userB);
  // 4. Attempt to retrieve a random trash entry ID as User B
  // Even though we can't create a real trash entry, the server should reject with authorization error
  const randomTrashEntryId = typia.random<string & tags.Format<"uuid">>();
  // 5. Validate unauthorized access rejection
  await TestValidator.error("access other user's trash entry", async () => {
    await api.functional.multiUserTodo.member.todos.trash_entries.at(
      userBConnection,
      {
        trashEntryId: randomTrashEntryId satisfies string as string,
      },
    );
  });
}

