  // 7. Test ownership validation
  await TestValidator.error(
    "non-owner cannot update filter setting",
    async () => {
      await api.functional.multiUserTodo.member.filter_settings.update(
        nonOwnerConnection,
        {
          filterSettingId: initialFilterSetting.id,
          body: updateBody,
        },
      );
    },
  );
}

