    TestValidator.predicate(
      "snapshot has updatedAt",
      typeof retrievedSnapshot.updatedAt === "string",
    );
    TestValidator.predicate(
      "snapshot has isCompleted",
      typeof retrievedSnapshot.isCompleted === "boolean",
    );
